/**
 * Componente ``Link`` para o sistema de hash routing. Renderiza
 * um ``<a>`` que atualiza o hash via ``writeRoute``.
 */

import { type AnchorHTMLAttributes, type MouseEvent, type ReactNode } from "react";
import { buildHash, type Route, writeRoute } from "@/lib/hash-route";

export interface LinkProps extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "href"> {
  to: Route;
  children: ReactNode;
}

export function Link({ to, children, onClick, className, ...rest }: LinkProps) {
  const handleClick = (e: MouseEvent<HTMLAnchorElement>) => {
    // Deixa o browser abrir em nova aba (Ctrl/Cmd+click) ou seguir o
    // link normalmente em outros casos — só interceptamos click simples.
    if (
      e.defaultPrevented ||
      e.button !== 0 ||
      e.metaKey ||
      e.ctrlKey ||
      e.shiftKey ||
      e.altKey
    ) {
      onClick?.(e);
      return;
    }
    e.preventDefault();
    writeRoute(to);
    onClick?.(e);
  };
  return (
    <a
      href={buildHash(to)}
      onClick={handleClick}
      className={className}
      {...rest}
    >
      {children}
    </a>
  );
}