/**
 * ``SourceCard`` — card de uma Source.
 */

import { useTranslation } from "react-i18next";
import { FileAudio, FileImage, FileText, Hash } from "lucide-react";
import { Link } from "@/lib/Link";
import { Badge } from "@/components/kg/Badge";
import type { SourceListItem } from "@/lib/types";
import { cn } from "@/lib/utils";

function pickIcon(mediaType: string | undefined, kind: string | undefined) {
  if (kind === "audio" || mediaType?.startsWith("audio/")) return FileAudio;
  if (kind === "image" || mediaType?.startsWith("image/")) return FileImage;
  return FileText;
}

export function SourceCard({
  source,
  className,
}: {
  source: SourceListItem;
  className?: string;
}) {
  const { t } = useTranslation();
  const Icon = pickIcon(source.media_type, source.source_kind);
  const total = source.chunks_total ?? 0;
  const atomized = source.chunks_atomized?.length ?? 0;
  const coverage = total > 0 ? Math.round((atomized / total) * 100) : 0;
  return (
    <Link
      to={{ kind: "source", id: source.id }}
      className={cn(
        // 2026-08-08 refactor: mesma hierarquia visual do NoteCard
        // (borda mais saturada no hover, accent 75, shadow-sm). Acrescenta
        // barra de progresso discreta para atomização no rodapé do card.
        "block rounded-lg border border-border bg-card p-4 text-card-foreground transition-all hover:border-primary/30 hover:bg-accent/75 hover:shadow-sm",
        className,
      )}
    >
      <div className="flex items-start gap-3">
        <Icon className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
        <div className="min-w-0 flex-1">
          <h3 className="truncate text-sm font-medium leading-snug">
            {/* Fallback é o id, não t("sources.title") — "Sources" (o
                header da seção) como título de card confunde o usuário.
                Mesma correção já aplicada em NoteCard. */}
            {source.title ?? source.id}
          </h3>
          <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            {source.source_kind && <Badge variant="outline">{source.source_kind}</Badge>}
            {source.media_type && <span className="font-mono">{source.media_type}</span>}
            <span className="flex items-center gap-1">
              <Hash className="h-3 w-3" aria-hidden />
              <span className="font-mono">{source.id}</span>
            </span>
          </div>
          <div className="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
            <span>
              {t("sources.chunksTotal")}: {total}
            </span>
            <span>
              {t("sources.chunksAtomized")}: {atomized}
            </span>
            {source.partially_atomized ? (
              <Badge variant="outline" className="text-[10px]">
                {t("sources.partiallyAtomized")}
              </Badge>
            ) : null}
          </div>
          {total > 0 && (
            <div
              className="mt-2 h-1 overflow-hidden rounded-full bg-muted"
              role="progressbar"
              aria-valuenow={coverage}
              aria-valuemin={0}
              aria-valuemax={100}
              title={`${coverage}%`}
            >
              <div
                className="h-full bg-primary/70 transition-[width]"
                style={{ width: `${coverage}%` }}
              />
            </div>
          )}
        </div>
      </div>
    </Link>
  );
}
