/**
 * ``useSource`` — leitura única de uma Source + navegação de chunks.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { readSource, readSourceChunk, ApiError } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import type { SourceReadResponse, ChunkResponse } from "@/lib/types";

export function useSource(sourceId: string | null): {
  source: SourceReadResponse | null;
  loading: boolean;
  error: string | null;
  readChunk: (index: number) => Promise<ChunkResponse | null>;
  /**
   * Erro da última leitura de chunk que **não** foi um 404. ``null``
   * quando a leitura deu certo ou quando o chunk simplesmente não existe
   * (fim do Source — condição esperada, não erro).
   */
  chunkError: string | null;
} {
  const { apiBase } = useKgClient();
  const [source, setSource] = useState<SourceReadResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [chunkError, setChunkError] = useState<string | null>(null);
  // Contador de geração, não ``cancelledRef`` boolean — Bug SPA-2/4
  // (revisão): o boolean é resetado para false a cada efeito de
  // mount/dep-change, então uma resposta ANTIGA (ex.: da Source
  // anterior, antes de navegar pra outra) chega DEPOIS do reset e
  // passava pelo guard. Com um contador, cada render captura o id e
  // só aplica o resultado se for o mais recente — sem FOUC de
  // Source anterior.
  const requestIdRef = useRef(0);

  useEffect(() => {
    if (!sourceId) {
      setSource(null);
      setLoading(false);
      return;
    }
    const requestId = ++requestIdRef.current;
    setLoading(true);
    void readSource(apiBase, sourceId)
      .then((d) => {
        if (requestIdRef.current !== requestId) return;
        setSource(d);
        setError(null);
      })
      .catch((e) => {
        if (requestIdRef.current !== requestId) return;
        setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
      })
      .finally(() => {
        if (requestIdRef.current === requestId) setLoading(false);
      });
  }, [apiBase, sourceId]);

  // M3 (bugfix-spa-2026-08-02): o ``catch { return null }`` original
  // apagava a diferença entre "esse chunk não existe" (404 — condição
  // normal ao chegar no fim do Source) e "o adapter caiu / devolveu 500 /
  // deu timeout". Em ambos os casos a UI mostrava para sempre o texto
  // "Loading…", sem nunca dizer que algo falhou. Agora o 404 continua
  // sendo ``null`` silencioso e o resto vira mensagem exibível.
  const readChunk = useCallback(
    async (index: number): Promise<ChunkResponse | null> => {
      if (!sourceId) return null;
      setChunkError(null);
      try {
        return await readSourceChunk(apiBase, sourceId, index);
      } catch (e) {
        if (e instanceof ApiError && e.status === 404) return null;
        setChunkError(
          e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message,
        );
        return null;
      }
    },
    [apiBase, sourceId],
  );

  return { source, loading, error, readChunk, chunkError };
}
