/**
 * Componentes de syntax highlighting para ``react-markdown``.
 * Usa ``react-syntax-highlighter`` (mesmo dep da WebUI) com tema
 * one-dark para consistência visual com CodeBlock.tsx da WebUI.
 */

import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { oneDark } from "react-syntax-highlighter/dist/esm/styles/prism";
import type { CSSProperties, ComponentProps } from "react";

type CodeProps = ComponentProps<"code"> & {
  inline?: boolean;
};

/** Handler de ``code`` para ``react-markdown`` — renderiza como bloco
 *  com syntax highlighting via Prism. */
export function MarkdownCode(props: CodeProps) {
  const { inline, className, children, ...rest } = props;
  const match = /language-(\w+)/.exec(className ?? "");
  if (inline || !match) {
    return (
      <code className={className} {...rest}>
        {children}
      </code>
    );
  }
  return (
    <SyntaxHighlighter
      style={oneDark as Record<string, CSSProperties>}
      language={match[1]}
      PreTag="div"
    >
      {String(children).replace(/\n$/, "")}
    </SyntaxHighlighter>
  );
}
