/**
 * ``useSearch`` — busca textual com debounce (200ms). React 18 hook
 * pattern: ``useTransition`` envolve os ``setHits`` para que a UI
 * possa mostrar feedback de pending (ex.: indicador de digitação)
 * sem bloquear input do humano.
 *
 * Aceita ``adapter`` (Fase 1 / B5): ``"memory"`` (CM), ``"acquire"`` (AK)
 * ou ``"both"`` (concatena hits de ambos bundles). Default mantém
 * comportamento histórico (``"memory"``).
 */

import { useEffect, useRef, useState, useTransition } from "react";
import { search, ApiError, type Adapter } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import type { SearchHit } from "@/lib/types";

const DEBOUNCE_MS = 200;

export type SearchAdapter = Adapter | "both";

export function useSearch(
  query: string,
  adapter: SearchAdapter = "memory",
): {
  hits: SearchHit[];
  loading: boolean;
  /** Erro fatal: ambos adapters falharam (em ``both``) ou o único
   *  adapter (em ``memory``/``acquire``) falhou. Não-bloqueante quando
   *  ``partialFailure`` é setado. */
  error: string | null;
  /** N5 (auditoria #2, 2026-07-31): nome do adapter que falhou
   *  quando em modo ``both`` e o outro respondeu. UI pode mostrar
   *  um banner amarelo não-bloqueante. ``null`` se tudo OK ou se
   *  ambos falharam (nesse caso ``error`` é setado). */
  partialFailure: "memory" | "acquire" | null;
  /** True quando uma ``startTransition`` ainda não commitou (busca
   *  em curso após digitação). False enquanto idle. */
  isPending: boolean;
} {
  const { apiBase } = useKgClient();
  const [hits, setHits] = useState<SearchHit[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [partialFailure, setPartialFailure] = useState<"memory" | "acquire" | null>(null);
  const [isPending, startTransition] = useTransition();
  const [debounced, setDebounced] = useState(query);
  // Bug SPA-2/4 (revisão): ``let cancelled = false`` no scope do
  // efeito é resetado quando ``apiBase`` muda, então uma resposta
  // ANTIGA de uma search anterior pode sobrescrever os hits com
  // stale data. Contador de geração resolve — o usuário digitando
  // "ab", "abc" rapidamente não vê hits da busca por "ab" depois de
  // ver os hits por "abc".
  const requestIdRef = useRef(0);

  // Debounce: aplica ``query`` em ``debounced`` após DEBOUNCE_MS.
  useEffect(() => {
    if (query === debounced) return;
    const t = setTimeout(() => setDebounced(query), DEBOUNCE_MS);
    return () => clearTimeout(t);
  }, [query, debounced]);

  // Run search quando ``debounced`` ou ``adapter`` mudam.
  useEffect(() => {
    if (!debounced.trim()) {
      startTransition(() => {
        setHits([]);
        setError(null);
      });
      setLoading(false);
      return;
    }
    const requestId = ++requestIdRef.current;
    // N1 (auditoria #2, 2026-07-31): limpa hits antes de novo fetch
    // para não exibir resultados antigos de uma query diferente.
    setHits([]);
    setError(null);
    setPartialFailure(null);
    setLoading(true);

    const adapters: Adapter[] = adapter === "both" ? ["memory", "acquire"] : [adapter];

    void Promise.allSettled(
      adapters.map((a) => search(apiBase, debounced, { adapter: a })),
    ).then((results) => {
      if (requestIdRef.current !== requestId) return;
      const merged: SearchHit[] = [];
      let lastError: string | null = null;
      // N5: rastreia qual adapter falhou quando só um falha em "both".
      // result[i] corresponde a adapters[i] na mesma ordem.
      let failedAdapter: "memory" | "acquire" | null = null;
      for (let i = 0; i < results.length; i++) {
        const r = results[i];
        const adapterName = adapters[i];
        if (r.status === "fulfilled") {
          merged.push(...r.value.results);
        } else {
          lastError = r.reason instanceof ApiError ? `HTTP ${r.reason.status}` : (r.reason as Error).message;
          if (adapter === "both") failedAdapter = adapterName;
        }
      }
      startTransition(() => {
        setHits(merged);
        // N5: detecta falha parcial em "both" (1 sucesso + 1 falha) e
        // expõe via ``partialFailure`` para a UI mostrar banner amarelo
        // sem bloquear os resultados. Falha total (ambos falham ou
        // single adapter falha) vira ``error`` bloqueante.
        //
        // Bug fix (revisão 2026-07-31): a versão anterior usava
        // ``merged.length > 0`` para decidir "falha parcial" — mas um
        // adapter que respondeu com sucesso e **zero hits legítimos**
        // (busca sem resultado) também tem ``merged.length === 0``,
        // então era classificado como erro bloqueante em vez de falha
        // parcial. O critério correto é "nem todos falharam", não
        // "algo veio nos resultados".
        const allFailed = results.every((r) => r.status === "rejected");
        const bothPartialFailure = adapter === "both" && failedAdapter !== null && !allFailed;
        setError(allFailed ? lastError : null);
        setPartialFailure(bothPartialFailure ? failedAdapter : null);
      });
      setLoading(false);
    });
  }, [apiBase, debounced, adapter, startTransition]);

  return { hits, loading, error, partialFailure, isPending };
}