/**
 * ``useStats`` / ``useStatsAll`` — leitura de stats dos adapters.
 *
 * - ``useStatsAll`` (Fase 1 / B4): bate em paralelo via ``Promise.allSettled``
 *   nos endpoints ``/memory/stats`` + ``/acquire/stats``. Se um adapter está
 *   down, retorna ``null`` para esse lado sem quebrar a UI. Default de
 *   substituição de ``useStats`` (DC-S3).
 * - ``useStats`` (mantido): wrapper backward-compat que retorna só CM.
 *   Reduz superfície de API por DC-S3 ("substitui").
 */

import { useEffect, useRef, useState } from "react";
import { stats, ApiError } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import type { StatsResponse } from "@/lib/types";

export interface UseStatsResult {
  stats: StatsResponse | null;
  loading: boolean;
  error: string | null;
}

/**
 * Backward-compat: retorna só stats do adapter ``memory`` (CM).
 * ``useStatsAll`` substitui em consumidores novos (HomeView, StatsView).
 */
export function useStats(): UseStatsResult {
  const { apiBase } = useKgClient();
  const [data, setData] = useState<StatsResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const requestIdRef = useRef(0);

  useEffect(() => {
    const requestId = ++requestIdRef.current;
    // N1 (auditoria #2, 2026-07-31): ao trocar apiBase (e.g. logout,
    // multi-tenant, hot reload), limpa o state anterior para não
    // exibir dados stale da apiBase antiga enquanto o novo fetch
    // está em curso. requestId garante que respostas antigas não
    // sobrescrevam as novas mesmo se chegarem fora de ordem.
    setData(null);
    setError(null);
    setLoading(true);
    void stats(apiBase, "memory")
      .then((d) => {
        if (requestIdRef.current !== requestId) return;
        setData(d);
        setError(null);
      })
      .catch((e) => {
        if (requestIdRef.current !== requestId) return;
        setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
      })
      .finally(() => {
        if (requestIdRef.current === requestId) setLoading(false);
      });
  }, [apiBase]);

  return { stats: data, loading, error };
}

export interface StatsAllResult {
  /** Stats de CM (collective-memory), ou ``null`` se adapter down. */
  memory: StatsResponse | null;
  /** Stats de AK (acquire-knowledge), ou ``null`` se adapter down. */
  acquire: StatsResponse | null;
  /** True enquanto o fetch de CM está em curso. */
  memoryLoading: boolean;
  /** True enquanto o fetch de AK está em curso. */
  acquireLoading: boolean;
  /** Compat: true enquanto **qualquer** um dos dois fetches está em curso. */
  loading: boolean;
  /** Mensagem de erro agregada — só setada se **ambos** os adapters falharem. */
  error: string | null;
}

/**
 * Lê stats de ambos os bundles (CM + AK) em paralelo.
 * Falha isolada de um adapter não quebra a UI; ela renderiza o lado que
 * deu certo e mostra estado neutro para o lado com ``null``.
 *
 * M1 (bugfix-spa-2026-08-02): antes um único ``Promise.allSettled``
 * resolvia os dois lados de uma vez e só então baixava ``loading``. Como
 * o timeout de cada request é 20s, um adapter down (que só falha no
 * timeout) segurava o ``loading`` global por 20s — e os consumidores
 * (``HomeView``, ``StatsView``) renderizam skeleton enquanto ``loading``.
 * Resultado: 20s de tela vazia mesmo com CM tendo respondido em 200ms.
 * Agora cada adapter tem sua própria cadeia e seu próprio flag.
 */
export function useStatsAll(): StatsAllResult {
  const { apiBase } = useKgClient();
  const [memory, setMemory] = useState<StatsResponse | null>(null);
  const [acquire, setAcquire] = useState<StatsResponse | null>(null);
  const [memoryLoading, setMemoryLoading] = useState(true);
  const [acquireLoading, setAcquireLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const requestIdRef = useRef(0);

  useEffect(() => {
    const requestId = ++requestIdRef.current;
    // N1 (auditoria #2, 2026-07-31): limpa state antes de novo fetch
    // para não exibir dados da apiBase anterior enquanto a nova
    // request está em curso. requestId garante idempotência se a
    // apiBase mudar várias vezes em sucessão.
    setMemory(null);
    setAcquire(null);
    setError(null);
    setMemoryLoading(true);
    setAcquireLoading(true);

    // ``error`` continua sendo agregado: só reportamos falha "dura" ao
    // usuário quando os DOIS lados falharam. Como as cadeias agora são
    // independentes, guardamos as mensagens aqui e o segundo ``catch`` a
    // chegar é quem publica o agregado.
    const failures: Partial<Record<"memory" | "acquire", string>> = {};
    const msgOf = (e: unknown): string =>
      e instanceof Error ? e.message : String(e);
    const publishIfBothFailed = () => {
      if (failures.memory === undefined || failures.acquire === undefined) return;
      setError(
        `Both CM and AK stats endpoints failed (CM: ${failures.memory}; AK: ${failures.acquire})`,
      );
    };

    void stats(apiBase, "memory")
      .then((d) => {
        if (requestIdRef.current !== requestId) return;
        setMemory(d);
      })
      .catch((e) => {
        if (requestIdRef.current !== requestId) return;
        failures.memory = msgOf(e);
        publishIfBothFailed();
      })
      .finally(() => {
        if (requestIdRef.current === requestId) setMemoryLoading(false);
      });

    void stats(apiBase, "acquire")
      .then((d) => {
        if (requestIdRef.current !== requestId) return;
        setAcquire(d);
      })
      .catch((e) => {
        if (requestIdRef.current !== requestId) return;
        failures.acquire = msgOf(e);
        publishIfBothFailed();
      })
      .finally(() => {
        if (requestIdRef.current === requestId) setAcquireLoading(false);
      });
  }, [apiBase]);

  return {
    memory,
    acquire,
    memoryLoading,
    acquireLoading,
    loading: memoryLoading || acquireLoading,
    error,
  };
}