/**
 * Adapter HTTP para os servidores do P6 (percival-collective-memory +
 * percival-acquire-knowledge).
 *
 * Endpoint base: ``/kg-interface/api/{memory|acquire}/...`` — o reverse
 * proxy do P10 (/kg-interface/api/memory/* → :8001, /kg-interface/api/acquire/*
 * → :8002) é o ponto único de entrada. Em dev, o `VITE_API_BASE` pode
 * apontar direto para as portas internas.
 *
 * Pattern idêntico à WebUI: ``ApiError`` class + ``fetchWithTimeout``.
 */

import { z } from "zod";
import { fetchWithTimeout } from "./http";
import {
  ChunkResponseSchema,
  FlagResultSchema,
  GraphResponseSchema,
  LifecycleResultSchema,
  MaintenanceResultSchema,
  ProtectedResultSchema,
  ResolveResultSchema,
  HealthResponseSchema,
  NoteHistoryResponseSchema,
  NoteListResponseSchema,
  NoteReadResponseSchema,
  SearchResponseSchema,
  SourceListResponseSchema,
  SourceReadResponseSchema,
  StatsResponseSchema,
  StorageSummarySchema,
  WriteBodyRequestSchema,
  WriteResultResponseSchema,
  type ChunkResponse,
  type FlagResult,
  type GraphResponse,
  type Lifecycle,
  type LifecycleResult,
  type MaintenanceResult,
  type ProtectedResult,
  type ResolveResult,
  type ReviewResolution,
  type HealthResponse,
  type NoteHistoryResponse,
  type NoteListResponse,
  type NoteReadResponse,
  type SearchResponse,
  type SourceListResponse,
  type SourceReadResponse,
  type StatsResponse,
  type StorageSummary,
  type WriteBodyRequest,
  type WriteResultResponse,
} from "./types";

/** Adapters conhecidos. O proxy do P10 expõe cada um em um path dedicado. */
export type Adapter = "memory" | "acquire";

export class ApiError extends Error {
  status: number;
  detail: unknown;
  constructor(status: number, message: string, detail?: unknown) {
    super(message);
    this.status = status;
    this.name = "ApiError";
    this.detail = detail;
  }
}

export class ApiContractError extends Error {
  /** Path ou rota que falhou a validação. */
  path: string;
  /** Erro Zod original. */
  cause: z.ZodError;
  constructor(path: string, cause: z.ZodError) {
    super(`API contract mismatch at ${path}: ${cause.message}`);
    this.name = "ApiContractError";
    this.path = path;
    this.cause = cause;
  }
}

const DEFAULT_TIMEOUT_MS = 20_000;
// ``git gc`` num repositório com milhares de objetos soltos leva alguns
// segundos — medido em ~1,3s no bundle real, mas cresce com o histórico.
const MAINTENANCE_TIMEOUT_MS = 120_000;

/**
 * Hook (Fase 3 / B9) — avisa no console do browser quando um schema Zod-root
 * descarta silenciosamente campos extras do payload (comportamento ``strip``
 * default do Zod). Dispara **só em DEV** (``import.meta.env.DEV``); em prod
 * silêncio total para não poluir DevTools de usuário final.
 */
export function warnDiscardedFields(
  schemaName: string,
  parsedData: unknown,
  actualJson: unknown,
): void {
  if (!import.meta.env.DEV) return;
  if (typeof actualJson !== "object" || actualJson === null) return;
  if (typeof parsedData !== "object" || parsedData === null) return;
  const actualKeys = Object.keys(actualJson as Record<string, unknown>);
  const parsedKeys = new Set(Object.keys(parsedData as Record<string, unknown>));
  const discarded = actualKeys.filter((k) => !parsedKeys.has(k));
  if (discarded.length > 0) {
    console.warn(
      `[kg-interface] Schema "${schemaName}" discarded ${discarded.length} extra field(s):`,
      discarded,
      "— abra o backend ou ative .passthrough() no schema.",
    );
  }
}

async function request<T>(
  base: string,
  url: string,
  init?: RequestInit,
  timeoutMs: number = DEFAULT_TIMEOUT_MS,
  schema?: z.ZodType<T, z.ZodTypeDef, unknown>,
): Promise<T> {
  const res = await fetchWithTimeout(
    `${base}${url}`,
    {
      ...(init ?? {}),
      credentials: "same-origin",
      headers: {
        Accept: "application/json",
        ...(init?.headers ?? {}),
      },
    },
    timeoutMs,
  );
  if (!res.ok) {
    const text = (await res.text()).trim();
    let parsed: unknown = text;
    try {
      parsed = text ? JSON.parse(text) : text;
    } catch {
      // not JSON — keep raw
    }
    throw new ApiError(res.status, text || `HTTP ${res.status}`, parsed);
  }
  // 204 ou body vazio → devolve ``undefined as T`` (caller decide o tipo)
  const text = await res.text();
  // M9 (bugfix-spa-2026-08-02): o caminho de SUCESSO parseava sem guard.
  // Um 200 com body não-JSON — o caso clássico é o dev server ou um
  // reverse proxy mal configurado devolvendo o ``index.html`` da SPA no
  // lugar da API — explodia com ``SyntaxError: Unexpected token '<'``,
  // que vazava cru para o ``error`` dos hooks e para o ErrorBoundary. É
  // uma falha de transporte, não um bug de render: vira ``ApiError``.
  let json: unknown;
  try {
    json = text ? JSON.parse(text) : undefined;
  } catch {
    const contentType = res.headers.get("content-type") ?? "";
    const sample = text.slice(0, 200);
    if (import.meta.env.DEV) {
      console.warn(
        `[kg-interface] non-JSON body for ${base}${url} (status=${res.status}, content-type=${contentType || "?"})`,
        sample,
      );
    }
    throw new ApiError(
      res.status,
      `Backend returned a non-JSON body (status=${res.status}, content-type=${contentType || "unknown"})`,
      { kind: "non-json-body", contentType, sample },
    );
  }
  if (!schema) return json as T;
  const parsed = schema.safeParse(json);
  if (!parsed.success) {
    throw new ApiContractError(url, parsed.error);
  }
  // Avisar (DEV only) se o backend enviou campos extras que o Zod-root
  // descartou silenciosamente (Fase 3 / B9).
  warnDiscardedFields(url, parsed.data, json);
  return parsed.data;
}

// ---------- Health (drives Sources card visibility) ----------

/**
 * ``health`` — testa se um adapter específico está online. O proxy do P10
 * serve cada adapter em um path dedicado (``/kg-interface/api/{memory|acquire}``);
 * um ``/healthz`` direto na raiz cairia no mesmo adapter — por isso o
 * adapter é parte do path. Em caso de rede down / adapter caído, lança
 * ``ApiError`` (status=0) ou error do fetch.
 */
export async function health(
  base: string,
  adapter: Adapter,
): Promise<HealthResponse> {
  return request<HealthResponse>(
    base,
    `/${adapter}/healthz`,
    undefined,
    5_000,
    HealthResponseSchema,
  );
}

export async function healthAll(base: string): Promise<Record<Adapter, boolean>> {
  const results = await Promise.allSettled([
    health(base, "memory"),
    health(base, "acquire"),
  ]);
  return {
    memory: results[0].status === "fulfilled",
    acquire: results[1].status === "fulfilled",
  };
}

// ---------- Collective-memory (memory adapter) ----------

export function listNotes(
  base: string,
  options: { q?: string; limit?: number; adapter?: Adapter } = {},
): Promise<NoteListResponse> {
  const adapter: Adapter = options.adapter ?? "memory";
  const params = new URLSearchParams();
  if (options.q) params.set("q", options.q);
  params.set("limit", String(options.limit ?? 50));
  return request<NoteListResponse>(
    base,
    `/${adapter}/notes?${params}`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    NoteListResponseSchema,
  );
}

export function readNote(
  base: string,
  noteId: string,
  adapter: Adapter = "memory",
): Promise<NoteReadResponse> {
  return request<NoteReadResponse>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    NoteReadResponseSchema,
  );
}

export function writeNoteBody(
  base: string,
  noteId: string,
  payload: WriteBodyRequest,
  adapter: Adapter = "memory",
): Promise<WriteResultResponse> {
  // Validação client-side antes de bater na API — o servidor também
  // valida (Pydantic), mas falhamos cedo no cliente.
  const parsed = WriteBodyRequestSchema.parse(payload);
  return request<WriteResultResponse>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}/body`,
    {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(parsed),
    },
    DEFAULT_TIMEOUT_MS,
    WriteResultResponseSchema,
  );
}

export function forgetNote(
  base: string,
  noteId: string,
  reason: string,
  adapter: Adapter = "memory",
): Promise<{ archived: string }> {
  // O adapter P6 (``tool_memory_forget``) devolve só ``{archived}`` — sem
  // ``id`` no payload. O tipo aqui refletia um campo que o backend nunca
  // manda.
  const params = new URLSearchParams({ reason });
  return request<{ archived: string }>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}?${params}`,
    { method: "DELETE" },
    DEFAULT_TIMEOUT_MS,
  );
}

export function noteHistory(
  base: string,
  noteId: string,
  limit = 20,
  adapter: Adapter = "memory",
): Promise<NoteHistoryResponse> {
  const params = new URLSearchParams({ limit: String(limit) });
  return request<NoteHistoryResponse>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}/history?${params}`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    NoteHistoryResponseSchema,
  );
}

export function search(
  base: string,
  q: string,
  options: { limit?: number; kind?: string; adapter?: Adapter } = {},
): Promise<SearchResponse> {
  const adapter: Adapter = options.adapter ?? "memory";
  const params = new URLSearchParams({ q });
  if (options.kind) params.set("kind", options.kind);
  params.set("limit", String(options.limit ?? 50));
  return request<SearchResponse>(
    base,
    `/${adapter}/search?${params}`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    SearchResponseSchema,
  );
}

export function stats(base: string, adapter: Adapter = "memory"): Promise<StatsResponse> {
  return request<StatsResponse>(
    base,
    `/${adapter}/stats`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    StatsResponseSchema,
  );
}

// ---------- P11: protected / lifecycle / review / storage ----------

/**
 * Liga/desliga o kill switch humano da nota.
 *
 * `expectedContentHash` é opcional mas recomendado quando a UI está
 * exibindo a nota: com ele o backend responde 409 se a nota mudou desde o
 * carregamento, em vez de sobrescrever a decisão de outra sessão.
 */
export function setProtected(
  base: string,
  noteId: string,
  protectedValue: boolean,
  opts: { reason?: string; expectedContentHash?: string } = {},
  adapter: Adapter = "memory",
): Promise<ProtectedResult> {
  return request<ProtectedResult>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}/protected`,
    {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        protected: protectedValue,
        reason: opts.reason ?? "manual toggle",
        expected_content_hash: opts.expectedContentHash ?? null,
      }),
    },
    DEFAULT_TIMEOUT_MS,
    ProtectedResultSchema,
  );
}

/**
 * Esfria (`cold`) ou reativa (`active`) a nota.
 *
 * A nota não sai de `notes/` — `cold` é uma flag no frontmatter. Esfriar
 * uma nota protegida exige `force: true`; reativar nunca é bloqueado.
 */
export function setLifecycle(
  base: string,
  noteId: string,
  lifecycle: Lifecycle,
  opts: { reason?: string; expectedContentHash?: string; force?: boolean } = {},
  adapter: Adapter = "memory",
): Promise<LifecycleResult> {
  return request<LifecycleResult>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}/lifecycle`,
    {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        lifecycle,
        reason: opts.reason ?? "lifecycle transition",
        expected_content_hash: opts.expectedContentHash ?? null,
        force: opts.force ?? false,
      }),
    },
    DEFAULT_TIMEOUT_MS,
    LifecycleResultSchema,
  );
}

/** Marca a nota para revisão humana estruturada. */
export function flagForReview(
  base: string,
  noteId: string,
  payload: {
    kind: string;
    confidence: "low" | "medium" | "high";
    reason: string;
    relatedActions?: string[];
    flaggedBy?: string;
  },
  adapter: Adapter = "memory",
): Promise<FlagResult> {
  return request<FlagResult>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}/flag`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        kind: payload.kind,
        confidence: payload.confidence,
        reason: payload.reason,
        related_actions: payload.relatedActions ?? null,
        flagged_by: payload.flaggedBy ?? "human:ui",
      }),
    },
    DEFAULT_TIMEOUT_MS,
    FlagResultSchema,
  );
}

/** Resolve — ou reabre (`reopen`) — uma entrada da fila de revisão. */
export function resolveReview(
  base: string,
  noteId: string,
  kind: string,
  resolution: ReviewResolution,
  reason = "manual resolve",
  adapter: Adapter = "memory",
): Promise<ResolveResult> {
  return request<ResolveResult>(
    base,
    `/${adapter}/notes/${encodeURIComponent(noteId)}/resolve`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ kind, resolution, reason }),
    },
    DEFAULT_TIMEOUT_MS,
    ResolveResultSchema,
  );
}

/** Uso de disco do bundle inteiro, `.git` incluído. */
export function storageStats(
  base: string,
  adapter: Adapter = "memory",
): Promise<StorageSummary> {
  return request<StorageSummary>(
    base,
    `/${adapter}/storage/stats`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    StorageSummarySchema,
  );
}

/**
 * Compacta o repositório git do bundle.
 *
 * Sem frase de confirmação de propósito: não reescreve histórico, não
 * expira reflog e não remove nota alguma. O timeout é maior que o padrão
 * porque `git gc` num repo grande leva alguns segundos.
 */
export function repoMaintenance(
  base: string,
  dryRun = true,
  adapter: Adapter = "memory",
): Promise<MaintenanceResult> {
  return request<MaintenanceResult>(
    base,
    `/${adapter}/storage/maintenance`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dry_run: dryRun, reason: "manual maintenance" }),
    },
    MAINTENANCE_TIMEOUT_MS,
    MaintenanceResultSchema,
  );
}

export function graph(base: string, adapter: Adapter = "memory"): Promise<GraphResponse> {
  return request<GraphResponse>(
    base,
    `/${adapter}/graph`,
    undefined,
    DEFAULT_TIMEOUT_MS,
    GraphResponseSchema,
  );
}

