import ReactDOM from "react-dom/client";

import App from "./App";
import "./globals.css";
import "./i18n";

// ``crypto.randomUUID`` só está definido em secure contexts (HTTPS ou
// localhost). LAN access via HTTP simples deixa ele undefined, o que
// crasha componentes que geram IDs client-side. Shim v4-ish para
// call sites ficarem uniformes entre secure e non-secure contexts.
if (typeof globalThis.crypto !== "undefined" && !("randomUUID" in globalThis.crypto)) {
  Object.defineProperty(globalThis.crypto, "randomUUID", {
    value: () =>
      "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        const v = c === "x" ? r : (r & 0x3) | 0x8;
        return v.toString(16);
      }),
    configurable: true,
  });
}

const root = document.getElementById("root");
if (!root) throw new Error("root element missing");

/* StrictMode disabled: dev double-invokes state updaters; debounce
   variants in useSearch must stay pure — same reason as WebUI. */
ReactDOM.createRoot(root).render(<App />);
