/**
 * ``ThemeToggle`` — botão de alternar tema (light/dark).
 *
 * Recebe ``theme``/``onToggle`` como props em vez de chamar ``useTheme()``
 * — a única instância do hook vive em ``KgShell`` (mesmo padrão da WebUI:
 * ``Shell`` chama o hook uma vez e passa ``toggle`` como prop). Chamar o
 * hook de novo aqui criaria um segundo ``useState`` de tema, dessincronizado
 * do primeiro.
 */

import { useTranslation } from "react-i18next";
import { Moon, Sun } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { Theme } from "@/hooks/useTheme";

export function ThemeToggle({
  theme,
  onToggle,
}: {
  theme: Theme;
  onToggle: () => void;
}) {
  const { t } = useTranslation();
  return (
    <Button
      variant="ghost"
      size="icon"
      onClick={onToggle}
      aria-label={t("common.theme")}
    >
      {theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
    </Button>
  );
}
