import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * ``cn`` — combina ``clsx`` (conditional className) com ``twMerge`` (Tailwind
 * class deduplication). Helper padrão do shadcn/ui, copiado verbatim
 * da WebUI do nanobot para garantir consistência.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}
