/**
 * ``GraphView`` — render do grafo via `<iframe sandbox>` view-only
 * (Fase 5 / B2).
 *
 * O P10 serve ``graphify-out/graph.html`` estaticamente, e o
 * ``graphify.serve`` expõe em outra porta (D67 do plano-mestre v2.4).
 * Por decisão do plano (D50), a render do grafo é **view-only** —
 * sem react-force-graph-2d / sigma.js, sem navegação nó→editor na v1.
 *
 * O humano navega pelo grafo via busca (`#/search?q=...`) ou lista
 * (`#/notes`). O iframe aqui serve como visualização rápida.
 *
 * Decisão DC-S5 — ``VITE_GRAPHIFY_URL`` opcional. Default
 * ``/kg-interface/graphify/graph.html``. Quando o backend expõe
 * ``graphify.serve`` em outro host, seta a env var.
 *
 * Decisão DC-S2 — seletor no header. Quando o bundle muda, o iframe
 * muda para a URL com o sufixo do bundle (ex.: ``?bundle=ak``) se o
 * graphify suportar. Fallback: o mesmo ``graph.html`` atende aos
 * dois bundles (D67 mescla antes do build).
 *
 * Refactor visual 2026-08-08: header com ícone Network + status bar
 * com ícones (Network/Link2/Clock/HardDrive/Layers) puxando nodes,
 * edges, last_build (relative time), size do grafo.json, bundle
 * ativo. Painel "Jump to note" permite digitar um id de nota e
 * navegar para ``#/notes/:id`` (ou ``#/extracted-notes/:id`` se o
 * adapter AK está ativo) — workaround para o iframe sandboxed que
 * não emite postMessage de cliques de nó.
 */

import { useTranslation } from "react-i18next";
import {
  Brain,
  Network,
  ExternalLink,
  ArrowRight,
  Loader2,
  Link2,
  Clock,
  HardDrive,
  Layers,
  Compass,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { BundleSelector } from "@/components/layout/BundleSelector";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { graph, ApiError } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import { useStatsAll } from "@/hooks/useStats";
import { useHashRoute } from "@/hooks/useHashRoute";
import { formatRelativeTime } from "@/lib/format";
import { useEffect, useRef, useState } from "react";
import type { GraphResponse } from "@/lib/types";
import { cn } from "@/lib/utils";

/** URL padrão do iframe de grafo. Configurável via VITE_GRAPHIFY_URL. */
const DEFAULT_GRAPHIFY_URL =
  (import.meta.env.VITE_GRAPHIFY_URL as string | undefined) ?? "/kg-interface/graphify/graph.html";

export function GraphView({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { apiBase, bundle } = useKgClient();
  const [, navigate] = useHashRoute();
  const [data, setData] = useState<GraphResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [iframeReady, setIframeReady] = useState(false);
  // Bug SPA-2/4 (revisão): ``let cancelled = false`` boolean
  // vulnerável a race — contador de geração resolve.
  const requestIdRef = useRef(0);
  // ``jumpId`` é o valor digitado no painel "Jump to note". Não é
  // persistido — o humano digita, clica, navega.
  const [jumpId, setJumpId] = useState("");

  // Stats puxam ``graph_health`` (nodes/edges/last_build). É independente
  // do ``/graph`` (que retorna metadados de arquivo) — em paralelo, sem
  // bloquear o iframe.
  const { memory } = useStatsAll();
  const graphHealth = memory?.graph_health ?? null;

  // Compose URL fora dos returns para que o ``useEffect`` de reset do
  // ``iframeReady`` possa observá-la. Recomputada a cada render.
  const url = new URL(DEFAULT_GRAPHIFY_URL, window.location.origin);
  url.searchParams.set("bundle", bundle);

  // N2 (auditoria #2, 2026-07-31): quando o bundle (ou apiBase) muda,
  // o iframe é re-renderizado com novo ``src`` mas o React **preserva
  // o elemento** (sem key change). O ``onLoad`` do iframe só dispara
  // **uma vez por mount** — não por src change. Resetar
  // ``iframeReady`` aqui força o overlay de loading a aparecer
  // enquanto o novo bundle carrega.
  const iframeUrl = url.toString();
  useEffect(() => {
    setIframeReady(false);
  }, [iframeUrl]);

  // ``GET /graph`` reporta sobre o ``graph.json``; o iframe precisa do
  // ``graph.html``. São artefatos DIFERENTES do graphify: o AK, por
  // exemplo, tinha ``graph.json`` (logo ``exists: true``) sem nenhum
  // ``graph.html`` exportado. Gatear o iframe por ``data.exists`` embutia
  // um iframe fadado a 404. Como o backend não descreve o HTML, sondamos
  // o próprio asset — mesma origin, sem mudança de contrato.
  const [assetOk, setAssetOk] = useState<boolean | null>(null);
  useEffect(() => {
    let cancelled = false;
    setAssetOk(null);
    fetch(iframeUrl, { method: "HEAD", credentials: "same-origin" })
      .then((r) => {
        if (!cancelled) setAssetOk(r.ok);
      })
      .catch(() => {
        if (!cancelled) setAssetOk(false);
      });
    return () => {
      cancelled = true;
    };
  }, [iframeUrl]);

  useEffect(() => {
    const requestId = ++requestIdRef.current;
    // N1 (auditoria #2, 2026-07-31): limpa ``data`` antes de novo
    // fetch para não exibir metadata de grafo da apiBase anterior.
    // requestId garante que respostas antigas não sobrescrevam.
    setData(null);
    setError(null);
    setLoading(true);
    void graph(apiBase)
      .then((d) => {
        if (requestIdRef.current !== requestId) return;
        setData(d);
      })
      .catch((e) => {
        // Bug SPA-3 (revisão): erros silenciados antes — ``data``
        // ficava null, ``loading`` virava false, e o caminho
        // ``!data || !data.exists`` engolia o erro sem mostrar nada.
        if (requestIdRef.current !== requestId) return;
        setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
      })
      .finally(() => {
        if (requestIdRef.current === requestId) setLoading(false);
      });
  }, [apiBase]);

  // "Jump to note" handler — navega para a nota digitada respeitando o
  // bundle ativo (CM → note, AK → extracted-note). Evita tentar
  // coordenar cliques de nó dentro do iframe sandboxed (impossível sem
  // cooperação do graphify via postMessage).
  const jumpToNote = () => {
    const id = jumpId.trim();
    if (!id) return;
    navigate({
      kind: bundle === "ak" ? "extracted-note" : "note",
      id,
      query: new URLSearchParams(),
    });
  };

  if (loading) return <SurfaceLoadingFallback className={className} />;
  if (error) return <EmptyStateI18n messageKey="errors.network" className={className} />;
  if (!data || !data.exists) {
    return (
      <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-6 overflow-y-auto p-6 md:p-8", className)}>
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
            <Brain className="h-5 w-5 text-muted-foreground" aria-hidden />
            {t("graph.title")}
          </h1>
          <EmptyStateI18n messageKey="graph.empty" />
        </div>
      );
    }
    // ``graph.json`` existe mas o export HTML não — estado legítimo (o
    // rebuild pode rodar com ``--no-viz``, ou o bundle nunca ter passado
    // pelo exportador). Dizer isso é melhor que embutir um iframe 404.
    if (assetOk === false) {
      return (
        <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-6 overflow-y-auto p-6 md:p-8", className)}>
          <h1 className="flex items-center gap-2 text-2xl font-semibold">
            <Brain className="h-5 w-5 text-muted-foreground" aria-hidden />
            {t("graph.title")}
          </h1>
        <EmptyStateI18n messageKey="graph.notExported" />
        <p className="text-xs text-muted-foreground">
          {data.path} · {Math.round(data.size_bytes / 1024)} KB · bundle={bundle}
        </p>
      </div>
    );
  }

  // Compose URL já calculado acima (fora do render condicional para
  // que o ``useEffect`` de reset do iframeReady possa observá-la).

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-4 p-6 md:p-8", className)}>
      {/* Header + actions. Rebrand 2026-08-09: o seletor CM/AK saiu
          do TopBar global e foi promovido para dentro desta página —
          o bundle só muda o ``?bundle=`` do iframe e a label da
          status bar, então expor o controle em todas as telas era
          ruído. Fica ao lado do "Open fullscreen" para manter o
          agrupamento visual de ações. */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex flex-col gap-1">
          <h1 className="flex items-center gap-2 text-2xl font-semibold">
            <Brain className="h-5 w-5 text-muted-foreground" aria-hidden />
            {t("graph.title")}
          </h1>
          {/* Subtitle com contagem do graph_health (não do arquivo). */}
          {graphHealth && (graphHealth.nodes !== undefined || graphHealth.edges !== undefined) ? (
            <p className="text-sm text-muted-foreground">
              {t("graph.subtitle", {
                nodes: graphHealth.nodes ?? 0,
                edges: graphHealth.edges ?? 0,
              })}
            </p>
          ) : (
            <p className="text-sm text-muted-foreground">{t("graph.subtitleNoStats")}</p>
          )}
        </div>
        <div className="flex items-center gap-2">
          <BundleSelector />
          <Button variant="outline" size="sm" asChild>
            <a href={iframeUrl} target="_blank" rel="noreferrer">
              <ExternalLink className="mr-1 h-3.5 w-3.5" aria-hidden />
              {t("graph.openFullscreen")}
            </a>
          </Button>
        </div>
      </div>

      {/* Painel "Jump to note" — workaround para navegação nó→nota.
          O iframe sandboxed não emite postMessage; em vez de tentar
          coordenar com o graphify via canal cross-frame, expomos um
          input direto para o humano digitar o id e pular. Não é
          "automático" como o graphify nativo, mas é simples e funciona
          sempre (independente da versão do graphify servido). */}
      <div className="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2">
        <Compass className="h-3.5 w-3.5 shrink-0 text-muted-foreground" aria-hidden />
        <Input
          value={jumpId}
          onChange={(e) => setJumpId(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") jumpToNote();
          }}
          placeholder={t("graph.jumpPlaceholder")}
          aria-label={t("graph.jumpPlaceholder")}
          className="h-7 flex-1 border-0 bg-transparent px-1 text-xs shadow-none focus-visible:ring-0"
        />
        <Button
          variant="ghost"
          size="sm"
          onClick={jumpToNote}
          disabled={!jumpId.trim()}
          className="h-7"
        >
          <ArrowRight className="mr-1 h-3.5 w-3.5" aria-hidden />
          {t("graph.jumpAction")}
        </Button>
      </div>

      {/* Banner D67 removido em 2026-08-08 — info redundante com a
          status bar (que mostra size + bundle + last_build). O
          humano que precisa do detalhe técnico continua tendo o
          doc-link no README. */}

      <div className="relative min-h-0 flex-1 overflow-hidden rounded-md border border-border bg-card">
        {/* B2 — iframe sandbox view-only (D50). Sem ``allow-same-origin``
            para isolar a SPA do conteúdo do grafo (defesa em profundidade).
            ``allow-scripts`` é necessário para que o graphify.serve
            renderize o canvas; ``allow-same-origin`` removido para evitar
            XSS via CSS injection ou DOM access. */}
        <iframe
          src={iframeUrl}
          sandbox="allow-scripts allow-forms"
          title={t("graph.title")}
          className="absolute inset-0 h-full w-full"
          onLoad={() => setIframeReady(true)}
        />
        {!iframeReady && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-background/70 text-sm text-muted-foreground backdrop-blur-sm">
            <Loader2 className="h-8 w-8 animate-spin text-primary" aria-hidden />
            <p>{t("graph.loading")}</p>
          </div>
        )}
      </div>

      {/* Status bar — substitui o footer técnico ("path · size · bundle")
          por uma faixa com ícones + labels. Mostra dados do graph.json
          (data.path, data.size_bytes) E do graph_health (nodes/edges/
          last_build) lado a lado. Em 2026-08-08 ganhou mais presença
          visual (borda primary/30, shadow-sm, ícones maiores, text-sm)
          para compensar a remoção do banner D67 — sem o banner, a
          status bar passa a ser o ponto de info técnico da página. */}
      <dl className="flex flex-wrap items-center gap-x-5 gap-y-2 rounded-md border border-primary/30 bg-card px-4 py-3 text-sm shadow-sm">
        <StatusItem
          icon={<Network className="h-4 w-4" aria-hidden />}
          label={t("graph.status.nodes")}
          value={graphHealth?.nodes}
        />
        <StatusItem
          icon={<Link2 className="h-4 w-4" aria-hidden />}
          label={t("graph.status.edges")}
          value={graphHealth?.edges}
        />
        <StatusItem
          icon={<Clock className="h-4 w-4" aria-hidden />}
          label={t("graph.status.lastBuild")}
          value={
            graphHealth?.last_build
              ? formatRelativeTime(graphHealth.last_build)
              : t("graph.status.never")
          }
        />
        <StatusItem
          icon={<HardDrive className="h-4 w-4" aria-hidden />}
          label={t("graph.status.size")}
          value={`${Math.round(data.size_bytes / 1024)} KB`}
        />
        <StatusItem
          icon={<Layers className="h-4 w-4" aria-hidden />}
          label={t("graph.status.bundle")}
          // Bundle ativo como label i18n (Memories / Learning) —
          // harmoniza com o seletor CM/AK na header. Raw ``"cm"`` /
          // ``"ak"`` era jargão técnico sem significado para o humano.
          value={t(bundle === "ak" ? "bundle.ak" : "bundle.cm")}
        />
        <span className="ml-auto font-mono text-xs text-muted-foreground/80" title={data.path}>
          {data.path}
        </span>
      </dl>
    </div>
  );
}

// ---------- Sub-componente local ----------

function StatusItem({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: number | string | undefined;
}) {
  if (value === undefined || value === null) return null;
  return (
    <span className="inline-flex items-center gap-1">
      {icon}
      <span className="font-medium text-foreground/80">{label}:</span>
      <span className="font-mono tabular-nums">{value}</span>
    </span>
  );
}