/**
 * ``useNote`` — leitura única de uma nota. Suporta ``refresh()`` para
 * recarregar depois de write.
 *
 * Aceita ``adapter`` (default ``"memory"``): notas do AK
 * (``"acquire"``) precisam de uma rota dedicada (``extracted-note``)
 * para não cair no CM via 404. O hook continua agnóstico ao caller —
 * é a view (que veio da rota) que decide qual adapter usar.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { readNote, writeNoteBody, forgetNote, ApiError, type Adapter } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import type { NoteReadResponse, WriteResultResponse } from "@/lib/types";

export interface UseNoteResult {
  note: NoteReadResponse | null;
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
  saveBody: (next: { body: string; baseBodyHash: string; reason?: string }) => Promise<WriteResultResponse>;
  archive: (reason: string) => Promise<{ archived: string }>;
}

export function useNote(noteId: string | null, adapter: Adapter = "memory"): UseNoteResult {
  const { apiBase } = useKgClient();
  const [note, setNote] = useState<NoteReadResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Contador de geração (não boolean): ``refresh`` é chamado tanto pelo
  // efeito de mount/dep-change quanto por callers externos (ex.: onSaved
  // do NoteEditor). Um ``cancelledRef`` boolean compartilhado é resetado
  // para ``false`` toda vez que o efeito roda de novo — se uma resposta
  // ANTIGA (ex.: da nota anterior, antes do usuário navegar) chega DEPOIS
  // desse reset, ela passa pelo guard e sobrescreve o estado com dados
  // errados. Com um contador, cada chamada de ``refresh`` captura o id da
  // geração atual e só aplica o resultado se ainda for a mais recente —
  // correto não importa a ordem de resolução das promises.
  const requestIdRef = useRef(0);

  const refresh = useCallback(async () => {
    const requestId = ++requestIdRef.current;
    if (!noteId) {
      setNote(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await readNote(apiBase, noteId, adapter);
      if (requestIdRef.current !== requestId) return;
      setNote(data);
      setError(null);
    } catch (e) {
      if (requestIdRef.current !== requestId) return;
      setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
    } finally {
      if (requestIdRef.current === requestId) setLoading(false);
    }
  }, [apiBase, noteId, adapter]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const saveBody = useCallback<UseNoteResult["saveBody"]>(
    async ({ body, baseBodyHash, reason }) => {
      if (!noteId) throw new Error("noteId is required");
      return writeNoteBody(apiBase, noteId, {
        body,
        base_body_hash: baseBodyHash,
        reason: reason ?? "edit body",
      }, adapter);
    },
    [apiBase, noteId, adapter],
  );

  const archive = useCallback<UseNoteResult["archive"]>(
    async (reason) => {
      if (!noteId) throw new Error("noteId is required");
      return forgetNote(apiBase, noteId, reason, adapter);
    },
    [apiBase, noteId, adapter],
  );

  return { note, loading, error, refresh, saveBody, archive };
}
