/**
 * ``KgShell`` — shell análogo ao ``Shell`` da WebUI (dentro de App.tsx):
 * Sidebar fixa + TopBar + <main> que faz branch sobre a rota atual do hash.
 *
 * Sem React Router (consistente com a WebUI — branch manual sobre
 * ``useHashRoute()``).
 *
 * ``useTheme()`` é chamado **uma única vez aqui** (mesmo padrão da WebUI:
 * ``Shell`` chama o hook e passa ``theme``/``toggle`` como props pro botão
 * de toggle — não cada componente que precisa dele chamando o hook de
 * novo). ``ThemeToggle`` chamar ``useTheme()`` por conta própria criaria
 * uma SEGUNDA instância de estado, independente desta — o toggle clicado
 * ali nunca se propagaria pro ``ThemeProvider``/``useThemeValue()`` lido
 * por outros componentes, porque são dois ``useState`` diferentes agindo
 * sobre o mesmo ``localStorage``/``documentElement`` sem se sincronizar
 * entre si.
 */

import { useHashRoute } from "@/hooks/useHashRoute";
import { useTheme, ThemeProvider } from "@/hooks/useTheme";
import { HealthProvider } from "@/hooks/useHealth";
import { Sidebar } from "@/components/layout/Sidebar";
import { TopBar } from "@/components/layout/TopBar";
import { HomeView } from "@/components/kg/HomeView";
import { NotesList } from "@/components/kg/NotesList";
import { NoteView } from "@/components/kg/NoteView";
import { NoteEdit } from "@/components/kg/NoteEdit";
import { ExtractedNotesList } from "@/components/kg/ExtractedNotesList";
import { ExtractedNoteView } from "@/components/kg/ExtractedNoteView";
import { ExtractedNoteEdit } from "@/components/kg/ExtractedNoteEdit";
import { SourcesList } from "@/components/kg/SourcesList";
import { SourceView } from "@/components/kg/SourceView";
import { SearchView } from "@/components/kg/SearchView";
import { GraphView } from "@/components/kg/GraphView";
import { StatsView } from "@/components/kg/StatsView";
import { NotFoundView } from "@/components/kg/NotFoundView";
import { ErrorBoundary } from "@/components/kg/ErrorBoundary";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";

export function KgShell() {
  const [route] = useHashRoute();
  const { theme, toggle } = useTheme();
  // Chave estável por "seção" de rota (não por route.id): navegar entre
  // duas notas não deve remontar a árvore, só entre kinds diferentes de
  // view — e remonta o ErrorBoundary quando o usuário navega pra longe de
  // uma view que quebrou, em vez de deixar o fallback de erro preso pra
  // sempre até um "Try again" manual (ErrorBoundary não reseta sozinho
  // quando ``children`` muda, só quando o componente é desmontado).
  // ``HealthProvider`` segue a mesma regra do ``ThemeProvider`` acima: o
  // health é resolvido UMA vez aqui e lido via contexto por Sidebar,
  // BundleSelector, os dois HealthPill e SourcesList. Cada um chamando o
  // hook por conta própria significava 2 requests por consumidor — 8
  // ``/healthz`` idênticos por navegação.
  return (
    <ThemeProvider theme={theme}>
      <HealthProvider>
        <div className="flex h-full w-full">
          <Sidebar className="hidden md:flex" />
          <div className="flex min-w-0 flex-1 flex-col">
            <TopBar theme={theme} onToggleTheme={toggle} />
            <main className="min-h-0 flex-1 overflow-hidden">
              <ErrorBoundary key={route.kind}>
                {renderRoute(route)}
              </ErrorBoundary>
            </main>
          </div>
        </div>
      </HealthProvider>
    </ThemeProvider>
  );
}

function renderRoute(route: ReturnType<typeof useHashRoute>[0]) {
  switch (route.kind) {
    case "home":
      return <HomeView />;
    case "notes":
      return <NotesList />;
    case "note":
      return route.id ? <NoteView noteId={route.id} /> : <NotesList />;
    case "note-edit":
      return route.id ? <NoteEdit noteId={route.id} /> : <NotesList />;
    case "extracted":
      return <ExtractedNotesList />;
    case "extracted-note":
      return route.id ? <ExtractedNoteView noteId={route.id} /> : <ExtractedNotesList />;
    case "extracted-note-edit":
      return route.id ? <ExtractedNoteEdit noteId={route.id} /> : <ExtractedNotesList />;
    case "sources":
      return <SourcesList />;
    case "source":
      return route.id ? <SourceView sourceId={route.id} /> : <SourcesList />;
    case "search":
      return <SearchView />;
    case "graph":
      return <GraphView />;
    case "stats":
      return <StatsView />;
    case "notFound":
      return <NotFoundView raw={route.raw} />;
    default:
      return <SurfaceLoadingFallback />;
  }
}
