/**
 * ``NotePreview`` — renderiza markdown com syntax highlighting.
 */

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { MarkdownCode } from "@/lib/markdown";

export function NotePreview({ body }: { body: string }) {
  return (
    <div className="prose prose-sm dark:prose-invert max-w-none">
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={{ code: MarkdownCode }}>
        {body}
      </ReactMarkdown>
    </div>
  );
}
