/**
 * App raiz. Wraps KgShell com KgClientProvider.
 *
 * ``useTheme`` (chamado uma única vez dentro de ``KgShell``, que também
 * provê o ``ThemeProvider`` — ver comentário lá) já aplica o tema em
 * ``document.documentElement`` via seu próprio useEffect. Componentes que
 * quiserem só LER o theme (não alternar) usam ``useThemeValue`` (helper
 * exportado pelo mesmo módulo do hook).
 */

import { KgClientProvider } from "@/providers/KgClientProvider";
import { KgShell } from "@/components/layout/KgShell";

export default function App() {
  return (
    <KgClientProvider>
      <KgShell />
    </KgClientProvider>
  );
}