/**
 * ``TopBar`` — barra superior com search global, bundle selector
 * (Fase 1 / B1), theme toggle, language switcher.
 */

import { useTranslation } from "react-i18next";
import { Search } from "lucide-react";
import { Input } from "@/components/ui/input";
import { ThemeToggle } from "@/components/layout/ThemeToggle";
import { LanguageSwitcher } from "@/components/layout/LanguageSwitcher";
import { HealthPill } from "@/components/layout/HealthPill";
import { useHashRoute } from "@/hooks/useHashRoute";
import type { Theme } from "@/hooks/useTheme";

export function TopBar({
  theme,
  onToggleTheme,
}: {
  theme: Theme;
  onToggleTheme: () => void;
}) {
  const { t } = useTranslation();
  const [, navigate] = useHashRoute();
  return (
    <header className="flex h-12 shrink-0 items-center gap-3 border-b border-border bg-background px-4">
      <form
        className="flex-1"
        onSubmit={(e) => {
          e.preventDefault();
          const data = new FormData(e.currentTarget);
          const q = String(data.get("q") ?? "").trim();
          if (!q) return;
          navigate({ kind: "search", query: new URLSearchParams({ q }) });
        }}
      >
        <div className="relative max-w-xl">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            name="q"
            type="search"
            placeholder={t("search.placeholder")}
            className="h-8 pl-9"
          />
        </div>
      </form>
      {/* H4 — estado dos adapters visível em todas as rotas (DC-BF-2 A).
          Escondidas abaixo de ``sm`` para não espremer o campo de busca
          em telas de 320px; o BundleSelector continua dando o feedback
          de AK down nesse caso. */}
      <div className="hidden shrink-0 items-center gap-1.5 sm:flex">
        <HealthPill adapter="memory" />
        <HealthPill adapter="acquire" />
      </div>
      <ThemeToggle theme={theme} onToggle={onToggleTheme} />
      <LanguageSwitcher />
    </header>
  );
}