/**
 * ``ExtractedNotesList`` — listagem de ExtractedNotes do AK (Fase 1 / B6).
 *
 * Análogo a ``NotesList`` mas bate em ``/acquire/notes`` (não CM). Reusa
 * ``NoteCard`` para o card visual — o tipo ``NoteListItem`` retornado
 * pelo AK é estruturalmente compatível (campos opcionais são "" ou
 * ``null`` no payload de ``/acquire/notes``).
 *
 * Aparece como item "Extracted" fixo na sidebar (decisão DC-S6),
 * independente do seletor de bundle.
 *
 * Refactor visual 2026-08-08: header com ícone Sprout + subtítulo com
 * ``count`` do payload. max-w-6xl / gap-3 / md:p-8 mantêm o padrão do
 * HomeView/StatsView.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Search, Sprout } from "lucide-react";
import { Input } from "@/components/ui/input";
import { NoteCard } from "@/components/kg/NoteCard";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { useKgClient } from "@/providers/KgClientProvider";
import { listNotes, ApiError } from "@/lib/api";
import type { NoteListItem } from "@/lib/types";
import { cn } from "@/lib/utils";

const DEBOUNCE_MS = 200;

export function ExtractedNotesList({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { apiBase } = useKgClient();
  const [q, setQ] = useState("");
  const [notes, setNotes] = useState<NoteListItem[]>([]);
  const [count, setCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [debouncedQ, setDebouncedQ] = useState("");
  const requestIdRef = useRef(0);

  // Debounce do q — mesmo padrão de useNotes.
  useEffect(() => {
    if (q === debouncedQ) return;
    const t = setTimeout(() => setDebouncedQ(q), DEBOUNCE_MS);
    return () => clearTimeout(t);
  }, [q, debouncedQ]);

  const refresh = useCallback(async () => {
    const requestId = ++requestIdRef.current;
    setLoading(true);
    try {
      const data = await listNotes(apiBase, { q: debouncedQ, adapter: "acquire", limit: 200 });
      if (requestIdRef.current !== requestId) return;
      setNotes(data.results);
      setCount(data.count);
      setError(null);
    } catch (e) {
      if (requestIdRef.current !== requestId) return;
      setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
    } finally {
      if (requestIdRef.current === requestId) setLoading(false);
    }
  }, [apiBase, debouncedQ]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-6 overflow-y-auto p-6 md:p-8", className)}>
      <header className="flex flex-col gap-1">
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
          <Sprout className="h-5 w-5 text-muted-foreground" aria-hidden />
          {t("extracted.title")}
        </h1>
        {!loading && (
          <p className="text-sm text-muted-foreground">
            {q
              ? t("extracted.subtitleFiltered", { count, q })
              : t("extracted.subtitle", { count })}
          </p>
        )}
      </header>
      <div className="relative">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t("extracted.searchPlaceholder")}
          className="pl-9"
        />
      </div>

      {loading ? (
        <SurfaceLoadingFallback />
      ) : error ? (
        <EmptyStateI18n messageKey="errors.network" />
      ) : notes.length === 0 ? (
        <EmptyStateI18n messageKey="extracted.empty" />
      ) : (
        <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">
          {notes.map((note) => (
            // ``adapter="acquire"`` → rota ``extracted-note`` (não CM).
            // Bugfix 2026-08-08: sem isso o card abria nota CM-only e
            // devolvia 404 → "Erro de rede".
            <NoteCard key={note.id} note={note} adapter="acquire" />
          ))}
        </div>
      )}
    </div>
  );
}