/**
 * ``SourcesList`` — listagem filtrada de Sources com search.
 *
 * B6 do plano-mestre v2.4: o card de Sources na sidebar é escondido
 * quando o adapter AK está down (``useHealth.health.acquire``) para
 * evitar EmptyState permanente; aqui a view inteira é guardada pela
 * mesma flag.
 *
 * Refactor visual 2026-08-08: header com ícone FolderOpen + subtítulo
 * com contagem + banner não-bloqueante quando AK está down (em vez de
 * EmptyState) para que o humano saiba que a página existe mas o
 * adapter está offline.
 */

import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { Search, FolderOpen, AlertCircle } from "lucide-react";
import { Input } from "@/components/ui/input";
import { SourceCard } from "@/components/kg/SourceCard";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { useHealth } from "@/hooks/useHealth";
import { useSources } from "@/hooks/useSources";
import { cn } from "@/lib/utils";

export function SourcesList({ className }: { className?: string }) {
  const { t } = useTranslation();
  const [q, setQ] = useState("");
  const { status } = useHealth();
  const { sources } = useSources();
  // Cacheia o filtro para que ``count``/``notes.length`` não recalculem
  // em todo render sem mudança de ``q``/``sources``.
  const filtered = useMemo(
    () =>
      sources.filter(
        (s) =>
          !q ||
          s.title?.toLowerCase().includes(q.toLowerCase()) ||
          s.id.includes(q),
      ),
    [sources, q],
  );
  const akDown = status.acquire === "error";

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-6 overflow-y-auto p-6 md:p-8", className)}>
      <header className="flex flex-col gap-1">
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
          <FolderOpen className="h-5 w-5 text-muted-foreground" aria-hidden />
          {t("sources.title")}
        </h1>
        <p className="text-sm text-muted-foreground">
          {q
            ? t("sources.subtitleFiltered", { count: filtered.length, total: sources.length, q })
            : t("sources.subtitle", { count: sources.length })}
        </p>
      </header>

      {akDown && (
        // B6 — banner amarelo não-bloqueante. Mantém Sources visíveis
        // se o humano chegou por deep-link; não esconde a página
        // inteira (UX ruim: deep-link prometia uma tela).
        <div
          role="status"
          className="flex items-start gap-2 rounded-md border border-amber-500/40 bg-amber-50/30 p-3 text-xs text-amber-900 dark:bg-amber-950/20 dark:text-amber-100"
        >
          <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden />
          <p>{t("sources.akDownHint")}</p>
        </div>
      )}

      <div className="relative">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t("sources.searchPlaceholder")}
          className="pl-9"
        />
      </div>

      {filtered.length === 0 ? (
        <EmptyStateI18n messageKey={q ? "sources.emptyFiltered" : "sources.empty"} />
      ) : (
        <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">
          {filtered.map((source) => (
            <SourceCard key={source.id} source={source} />
          ))}
        </div>
      )}
    </div>
  );
}