/**
 * ``EmptyState`` — placeholder amigável quando não há dados.
 */

import { useTranslation } from "react-i18next";
import { Inbox } from "lucide-react";
import { cn } from "@/lib/utils";

export function EmptyState({
  message,
  className,
}: {
  message: string;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-2 rounded-md border border-dashed border-border p-8 text-center text-sm text-muted-foreground",
        className,
      )}
    >
      <Inbox className="h-6 w-6 opacity-50" />
      <p>{message}</p>
    </div>
  );
}

export function EmptyStateI18n({
  messageKey,
  className,
}: {
  messageKey: string;
  className?: string;
}) {
  const { t } = useTranslation();
  return <EmptyState message={t(messageKey)} className={className} />;
}
