/**
 * ``NotFoundView`` — 404 explícito para rotas de hash desconhecidas
 * (M10 do plano ``bugfix-spa-2026-08-02``, decisão DC-BF-3 opção B).
 *
 * Antes, ``parseHash`` devolvia a Home para qualquer path que não
 * reconhecesse. O sintoma reportado foi ``#/new``: a URL permanecia
 * ``#/new``, a Home renderizava, e não havia nada indicando que a rota
 * não existe. Implementar "criar nota" de fato é feature, não bugfix —
 * fica para o plano ``spa/`` (B14 / DC-S2).
 */

import { useTranslation } from "react-i18next";
import { FileQuestion } from "lucide-react";
import { Link } from "@/lib/Link";
import { cn } from "@/lib/utils";

export function NotFoundView({
  raw,
  className,
}: {
  raw?: string;
  className?: string;
}) {
  const { t } = useTranslation();
  return (
    <div
      className={cn(
        "flex h-full flex-col items-center justify-center gap-3 p-6 text-center",
        className,
      )}
    >
      <FileQuestion className="h-8 w-8 text-muted-foreground" />
      <h1 className="text-lg font-semibold">{t("notFound.title")}</h1>
      <p className="max-w-md text-sm text-muted-foreground">
        {t("notFound.body", { path: raw ?? "?" })}
      </p>
      <Link
        to={{ kind: "home" }}
        className="rounded-md border border-border bg-card px-3 py-1 text-xs hover:bg-accent"
      >
        {t("notFound.backHome")}
      </Link>
    </div>
  );
}
