/**
 * ``ErrorBoundary`` — captura erros de render e exibe mensagem amigável.
 * Pattern idêntico ao ErrorBoundary do React 18.
 */

import { Component, type ErrorInfo, type ReactNode } from "react";
import { AlertTriangle } from "lucide-react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    // L4 (bugfix-spa-2026-08-02): em produção o erro já é comunicado ao
    // humano pelo fallback visual abaixo. O ``console.error`` extra só
    // polui o DevTools do usuário final e é coletado como incidente por
    // ferramentas externas (Sentry/Rollbar) que ainda não temos
    // configuradas — ruído sem destinatário. Em dev continua vindo
    // completo, com o component stack.
    if (import.meta.env.DEV) {
      console.error("ErrorBoundary caught", error, info);
    }
  }

  reset = () => this.setState({ error: null });

  render() {
    if (this.state.error) {
      if (this.props.fallback) {
        return this.props.fallback(this.state.error, this.reset);
      }
      return (
        <div className="flex h-full flex-col items-center justify-center gap-3 p-6 text-center">
          <AlertTriangle className="h-8 w-8 text-destructive" />
          <p className="text-sm font-medium text-destructive">
            {this.state.error.message}
          </p>
          <button
            type="button"
            className="rounded-md border border-border bg-card px-3 py-1 text-xs hover:bg-accent"
            onClick={this.reset}
          >
            Try again
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}
